//! Queue tags (SPEC-feature section 3).

use std::collections::BTreeMap;

use serde_json::{Value, json};

use super::{Broker, Members, members};
use crate::error::{Error, ErrorCode, Result};
use crate::naming;
use crate::request::Params;

const MAX_TAGS: usize = 50;
const MAX_KEY_CHARS: usize = 128;
const MAX_VALUE_BYTES: usize = 256;

fn invalid(message: String) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, message)
}

fn check_key(key: &str) -> Result<()> {
    if naming::is_identifier(key, MAX_KEY_CHARS) {
        Ok(())
    } else {
        Err(invalid(format!(
            "tag key `{key}` must be 1 to {MAX_KEY_CHARS} characters from A-Z a-z 0-9 _ -"
        )))
    }
}

fn parse_tags(params: Params<'_>) -> Result<BTreeMap<String, String>> {
    let tags = params.object("Tags")?.expect("required");
    tags.members()
        .iter()
        .map(|(key, value)| {
            check_key(key)?;
            match value.as_str() {
                Some(v) if v.len() <= MAX_VALUE_BYTES => Ok((key.clone(), v.to_owned())),
                _ => Err(invalid(format!(
                    "the value of tag `{key}` must be a string of at most {MAX_VALUE_BYTES} bytes"
                ))),
            }
        })
        .collect()
}

fn parse_keys(params: Params<'_>) -> Result<Vec<String>> {
    params
        .array("TagKeys")?
        .expect("required")
        .iter()
        .map(|key| {
            let key = key
                .as_str()
                .ok_or_else(|| invalid("`TagKeys` must contain strings".into()))?;
            check_key(key)?;
            Ok(key.to_owned())
        })
        .collect()
}

impl Broker {
    pub(super) fn tag_queue(&mut self, params: Params<'_>) -> Result<Members> {
        params.require(&["QueueName", "Tags"])?;
        let name = params.string("QueueName")?.expect("required");
        let tags = parse_tags(params)?;

        let queue = self.queue_mut(name)?;
        let new_keys = tags.keys().filter(|k| !queue.tags.contains_key(*k)).count();
        if queue.tags.len() + new_keys > MAX_TAGS {
            return Err(Error::new(
                ErrorCode::LimitExceeded,
                format!("a queue carries at most {MAX_TAGS} tags"),
            ));
        }
        queue.tags.extend(tags);
        Ok(Members::new())
    }

    pub(super) fn untag_queue(&mut self, params: Params<'_>) -> Result<Members> {
        params.require(&["QueueName", "TagKeys"])?;
        let name = params.string("QueueName")?.expect("required");
        let keys = parse_keys(params)?;

        let queue = self.queue_mut(name)?;
        for key in keys {
            queue.tags.remove(&key);
        }
        Ok(Members::new())
    }

    pub(super) fn list_queue_tags(&mut self, params: Params<'_>) -> Result<Members> {
        params.require(&["QueueName"])?;
        let name = params.string("QueueName")?.expect("required");
        let queue = self.queue_mut(name)?;
        let tags: serde_json::Map<String, Value> = queue
            .tags
            .iter()
            .map(|(k, v)| (k.clone(), json!(v)))
            .collect();
        Ok(members([("Tags", Value::Object(tags))]))
    }
}
